//! Keycap images for the Keybindings page: one embedded PNG
//! per keyboard key, drawn in the app palette (assets/keycaps,
//! generated by the keycap script — labels are exact because
//! they are drawn, not photographed).
//!
//! A binding whose every token resolves to a cap renders as
//! a row of caps; anything else (axes, gamepad tokens,
//! unmapped names) returns `None` here and the caller keeps
//! the humanized text chip, so bindings with no caps are
//! untouched by this module. Mouse buttons and the wheel
//! have caps of their own (a top-down mouse with the pressed
//! part lit).

use std::collections::HashMap;
use std::sync::OnceLock;

use iced::widget::image::Handle;

/// One keycap: its image and its width in key units
/// (1.0 = a standard square key), for proportional layout.
#[derive(Debug, Clone)]
pub struct Cap {
    pub handle: Handle,
    pub units: f32,
}

macro_rules! cap {
    ($file:literal, $units:expr) => {
        Cap {
            handle: Handle::from_bytes(
                include_bytes!(concat!("../../assets/keycaps/", $file)).to_vec(),
            ),
            units: $units,
        }
    };
}

