/// The cap name one FS25 input token (the part after `KEY_`,
/// any case) resolves to, or `None` when the token has no
/// cap. Sided modifiers share one cap; FS names that differ
/// from the cap names are aliased here.
fn cap_name(token: &str) -> Option<String> {
    let t = token.to_lowercase();
    let name = match t.as_str() {
        "lshift" | "rshift" => "shift".to_string(),
        "lctrl" | "rctrl" => "ctrl".to_string(),
        "lalt" | "ralt" => "alt".to_string(),
        "lwin" | "rwin" => "win".to_string(),
        "return" => "enter".to_string(),
        "escape" => "esc".to_string(),
        "quote" => "apostrophe".to_string(),
        "leftbracket" => "lbracket".to_string(),
        "rightbracket" => "rbracket".to_string(),
        "kp_period" => "kp_decimal".to_string(),
        _ => t,
    };
    if cap_map().contains_key(name.as_str()) {
        Some(name)
    } else {
        None
    }
}

/// The cap name one FS25 mouse token (the part after
/// `MOUSE_`, any case) resolves to, or `None` when the
/// token has no cap.
fn mouse_cap_name(token: &str) -> Option<String> {
    let name = match token.to_lowercase().as_str() {
        "button_left" => "mouse_left",
        "button_right" => "mouse_right",
        "button_middle" => "mouse_middle",
        "button_4" => "mouse_button_4",
        "button_5" => "mouse_button_5",
        "wheel_up" => "mouse_wheel_up",
        "wheel_down" => "mouse_wheel_down",
        "wheel_left" => "mouse_wheel_left",
        "wheel_right" => "mouse_wheel_right",
        _ => return None,
    };
    if cap_map().contains_key(name) {
        Some(name.to_string())
    } else {
        None
    }
}

/// One input token's cap, whether it names a keyboard key
/// (`KEY_...`) or a mouse part (`MOUSE_...`).
fn token_cap(token: &str) -> Option<Cap> {
    let name = if let Some(rest) = token.strip_prefix("KEY_") {
        cap_name(rest)?
    } else if let Some(rest) = token.strip_prefix("MOUSE_") {
        mouse_cap_name(rest)?
    } else if let Some(rest) = token.strip_prefix("BUTTON_") {
        // A bare BUTTON_n lives on a gamepad or a wheel —
        // the numbered round cap serves both.
        let n: u32 = rest.parse().ok()?;
        if !(1..=24).contains(&n) {
            return None;
        }
        format!("pad_{}", n)
    } else if let Some(rest) = token.strip_prefix("AXIS_") {
        let n: u32 = rest.parse().ok()?;
        if !(1..=8).contains(&n) {
            return None;
        }
        format!("axis_{}", n)
    } else {
        return None;
    };
    cap_map().get(name.as_str()).cloned()
}

/// The caps for one binding input ("KEY_lshift KEY_n"), in
/// order — or `None` when the input is empty or any token
/// has no cap (an axis, a gamepad token, an unknown name),
/// in which case the binding keeps its text rendering.
pub fn binding_caps(input: &str) -> Option<Vec<Cap>> {
    let tokens: Vec<&str> = input.split(' ').filter(|t| !t.is_empty()).collect();
    if tokens.is_empty() {
        return None;
    }
    let mut out = Vec::with_capacity(tokens.len());
    for token in tokens {
        out.push(token_cap(token)?);
    }
    Some(out)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn combo_resolves_in_order() {
        let caps = binding_caps("KEY_lshift KEY_n").expect("combo has caps");
        assert_eq!(caps.len(), 2);
        assert_eq!(caps[0].units, 2.25); // shift
        assert_eq!(caps[1].units, 1.0); // n
    }

    #[test]
    fn fs_aliases_resolve() {
        for input in [
            "KEY_return",
            "KEY_escape",
            "KEY_quote",
            "KEY_leftbracket",
            "KEY_KP_1",
            "KEY_KP_period",
            "KEY_KP_enter",
            "KEY_rctrl",
            "KEY_capslock",
            "KEY_space",
            "KEY_f12",
            "KEY_pause",
        ] {
            assert!(binding_caps(input).is_some(), "{input} should have a cap");
        }
    }

    #[test]
    fn mouse_inputs_resolve() {
        for input in [
            "MOUSE_BUTTON_LEFT",
            "MOUSE_BUTTON_RIGHT",
            "MOUSE_BUTTON_MIDDLE",
            "MOUSE_BUTTON_4",
            "MOUSE_BUTTON_5",
            "MOUSE_WHEEL_UP",
            "MOUSE_WHEEL_DOWN",
            "MOUSE_WHEEL_LEFT",
            "MOUSE_WHEEL_RIGHT",
        ] {
            assert!(binding_caps(input).is_some(), "{input} should have a cap");
        }
        // Keyboard and mouse mix freely in one binding now.
        let caps = binding_caps("KEY_lshift MOUSE_BUTTON_RIGHT").expect("mixed has caps");
        assert_eq!(caps.len(), 2);
    }

    #[test]
    fn non_keyboard_inputs_have_no_caps() {
        for input in [
            "AXIS_X",
            "BUTTON_25", // past the drawn set
            "",
            "MOUSE_BUTTON_9", // a mouse token with no cap drawn
            "KEY_lshift AXIS_X+", // one unmapped token sinks the row
        ] {
            assert!(binding_caps(input).is_none(), "{input:?} should not");
        }
    }

    #[test]
    fn gamepad_and_axis_inputs_resolve() {
        for input in ["BUTTON_1", "BUTTON_5", "BUTTON_24", "AXIS_1", "AXIS_8"] {
            assert!(binding_caps(input).is_some(), "{input} should have a cap");
        }
        let caps = binding_caps("AXIS_3").expect("axis has a cap");
        assert_eq!(caps[0].units, 1.5);
    }

    #[test]
    fn space_is_wide() {
        let caps = binding_caps("KEY_space").expect("space has a cap");
        assert_eq!(caps[0].units, 6.25);
    }
}
